insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d2027ed3-7670-4963-9212-4e48cccf8097', 'es', '¿Qué pasa cuando retomas hilos en lugar de saltar a preguntas nuevas?', '["La conversación se siente más natural y menos como una entrevista", "Se siente escuchada porque respondes a lo que te contó", "Las dos anteriores"]'::jsonb, 'Retomar hilos demuestra presencia y atención; usa su último detalle como tu siguiente paso.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('999bda2b-2b88-4a84-bd9c-d736ccb07089', 'es', 'Te dice: “Trabajo en marketing”. ¿Qué respuesta demuestra que sabes retomar el hilo?', '["“Qué bien. ¿Y de dónde eres?”", "“Yo también tengo un amigo en marketing. El mundo es un pañuelo.”", "“Ah, qué bien. Yo trabajo en finanzas.”", "“El marketing es interesante. ¿De qué tipo? ¿Redes sociales, marca, análisis de datos?”"]'::jsonb, 'Retomar el hilo significa profundizar en su tema; pregunta detalles sobre lo que mencionó.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2923827f-429f-4dd6-ac88-436a5a9dbbc6', 'es', '¿Cómo deberías elegir qué hilo seguir?', '["Elegir un detalle que te interese", "Usar una lista de preguntas preparada", "Construir sobre algo concreto que te contó"]'::jsonb, 'Cualquier detalle que ella aporte puede hacer avanzar la conversación; elige el que te despierte curiosidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('29feaa96-2d35-4ba5-9ebd-71eb7f487487', 'es', '¿Por qué depender solo de preguntas puede hacer que la conversación se sienta tensa?', '["Las preguntas hacen más lenta la conversación", "Las preguntas le pasan una y otra vez la responsabilidad a ella", "Las preguntas suenan ensayadas", "Las preguntas reducen la atracción"]'::jsonb, 'Demasiadas preguntas crean una dinámica de interrogatorio en la que ella carga con la conversación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('52edb21f-05cb-41ea-a94c-5ec38eca6a8d', 'es', '¿Qué logran los comentarios y las observaciones que las preguntas no logran?', '["Demuestran seguridad al compartir tu punto de vista", "Muestran que eres lo bastante interesante como para compartir lo que piensas", "Abren la puerta a una respuesta sin exigirla"]'::jsonb, 'Las observaciones le dan algo a lo que responder sin la carga de tener que contestar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('89a9c6b7-ea88-49ca-a0b1-19c9f94287cd', 'es', '¿Qué respuestas son observaciones o comentarios, y no preguntas para sacarle información?', '["“Tienes cara de que necesitabas ese trago.”", "“Suena agotador.”", "“¿Sueles trabajar hasta tarde?”", "“Este lugar se pone imposible los fines de semana.”"]'::jsonb, 'Estas aportan contexto o un punto de vista en lugar de pedir más información.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a8dcf867-454f-44e9-b824-f823389b43f0', 'es', '¿Qué define mejor un buen ritmo en una conversación?', '["Hablar con seguridad y sin pausas", "Dejar que ella lleve todo", "Llenar los silencios lo más rápido posible", "Un ida y vuelta constante en el que los dos aportan"]'::jsonb, 'El ritmo nace de que los dos aporten, no de hablar sin parar ni de quedarte totalmente pasivo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3b838c1a-69b1-4328-9785-cd16d57ae3b6', 'es', 'Menciona un viaje reciente. Tú también fuiste a ese lugar. ¿Cómo podrías responder?', '["Contarle todo lo que hiciste en tu viaje", "Decir “Sí, yo también fui” y nada más", "Compartir una frase y luego invitarla a contar más"]'::jsonb, 'Aportar algo breve y luego dejarle espacio mantiene un ritmo compartido.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2760f510-bd8b-4ac3-bab9-6e67951fb689', 'es', '¿Por qué acaparar la conversación hace que ella se implique menos?', '["Le impide aportar", "Crea un monólogo de un solo lado", "Muestra que la escuchas activamente"]'::jsonb, 'Acaparar le quita espacio a ella y rompe el equilibrio del ritmo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6e149fa3-93c4-42b2-9c8e-f7f88712cc49', 'es', 'Termina de explicarte una decisión difícil y te mira. ¿Cuál es la mejor respuesta?', '["Tranquilizarla de inmediato", "Darle un consejo enseguida", "Hacer una breve pausa, sostener la mirada y luego responder", "Cambiar de tema para aligerar el ambiente"]'::jsonb, 'Una breve pausa muestra que estás procesando sus palabras e invita a ir más a fondo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f100da89-837b-4ce4-89f0-13a05418c184', 'es', 'Le haces una pregunta profunda. Se queda pensando antes de responder. ¿Qué deberías hacer?', '["Intervenir para ayudarla", "Reformular la pregunta", "Añadir otra pregunta", "Sostener el silencio y dejarla pensar"]'::jsonb, 'Dejarla pensar sin presión demuestra paciencia y seguridad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('af284377-c4c0-42ca-a6f4-112ce777e549', 'es', '¿Cuándo es más eficaz el silencio en una conversación?', '["Después de que ella cuente algo personal", "Cuando no sabes qué decir", "Justo antes de hacer un comentario pensado", "Para no tener que aportar nada"]'::jsonb, 'El silencio funciona cuando da pie a reflexionar o añade peso, no cuando sustituye la participación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5d75efc2-36fb-47a3-9f27-cb0833551415', 'es', '¿Qué es el subtexto en una conversación?', '["Las palabras exactas que se dicen", "El significado emocional detrás de las palabras", "Solo el volumen de su voz", "Lo largas que son sus frases"]'::jsonb, 'El subtexto es la distancia entre lo que se dice y lo que se siente por debajo. Responde a eso.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9fe24bb8-edce-4a11-ac05-37dcfca6822d', 'es', 'Te dice “Me acabo de mudar aquí” en un tono bajo e inseguro. ¿Qué respuesta muestra sensibilidad?', '["“¿De dónde te mudaste?”", "“¿Y te está gustando?”", "“Eso puede ser mucho. ¿Cómo te estás adaptando?”", "“¿A qué te dedicas?”"]'::jsonb, 'Esta respuesta reconoce la capa emocional que deja ver su tono.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4434c17e-e1bd-4981-8ea6-566ffaae5de4', 'es', '¿Qué errores te impiden captar el subtexto?', '["Escuchar solo palabras clave", "Planear tu siguiente pregunta", "Prestar atención al tono y al ritmo"]'::jsonb, 'El subtexto se pierde cuando tu atención está en sacar información y no en estar presente. Está presente.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('69b81da3-8a21-43e7-9c1f-52aedcb7f44f', 'es', '¿Qué significa escuchar para entender?', '["Esperar con educación a que te toque hablar", "Preparar una respuesta pensada mientras ella habla", "Darle la razón en todo lo que dice", "Estar plenamente presente en lo que te está comunicando"]'::jsonb, 'Escuchar para entender significa dar prioridad a comprender por encima de preparar tu respuesta.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94878e49-fd86-4e6f-8398-cdb055f272a3', 'es', '¿Por qué planear tu respuesta mientras ella habla reduce la conexión?', '["Hace más lenta la conversación", "Te hace sonar como si leyeras un guion", "Aumenta los silencios", "Aleja tu atención de lo que ella quiere decir"]'::jsonb, 'Planear de antemano dirige tu atención hacia dentro y te hace perder matices y subtexto.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e596b988-c6fd-4182-add2-2c2b0eeb4cc4', 'es', '¿Qué respuestas muestran que escuchaste para entender?', '["Ofrecerle soluciones de inmediato", "Nombrar el sentimiento que dejó entrever", "Hacer una pausa antes de responder", "Construir directamente sobre su última frase"]'::jsonb, 'Entender nace de estar presente, no de arreglar las cosas ni de lucir tu perspicacia.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5e09607d-070f-41c5-af20-c696a61f1329', 'es', '¿Para qué sirve reconocer su respuesta antes de seguir con la conversación?', '["Para mostrar que sus palabras se entendieron e importaron", "Para hacer más lenta la conversación a propósito", "Para sonar emocionalmente inteligente", "Para no tener que hacer preguntas de seguimiento"]'::jsonb, 'Reconocer lo que dijo muestra que su mensaje llegó antes de que la conversación siga.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0af9f869-b543-4bea-bfe5-e3c0c0722302', 'es', 'Te dice: “Mi hermana y yo ya casi no nos vemos”. ¿Cuál es la mejor respuesta?', '["“Así es la vida.”", "“¿Cuántos años tiene?”", "“La distancia puede ser difícil. ¿Hablan a menudo?”", "“¿Dónde vive ahora?”"]'::jsonb, 'Nombrar la realidad emocional antes de preguntar mantiene el momento humano.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0810f6d9-5a61-4b89-b159-0607132c5f66', 'es', '¿Qué frases cuentan como reconocimiento?', '["“Suena a que te costó esfuerzo.”", "“¿Por qué hiciste eso?”", "“Entiendo por qué eso era importante para ti.”", "“Qué bien.”"]'::jsonb, 'Reconocer es validar el significado o el esfuerzo, no solo el contenido.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8e246a4f-c248-490c-956f-77029e0a2ad4', 'es', '¿Qué son las señales no verbales de escucha?', '["Señales del lenguaje corporal que comunican interés y atención", "Expresiones faciales que muestran reacciones emocionales a lo que dice", "Ajustes de postura que demuestran escucha activa", "Todas las anteriores"]'::jsonb, 'Las señales no verbales comunican que estás presente y procesando sus palabras.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('61372c16-e1e3-47b9-b21c-d9331ef4e852', 'es', 'Te está contando una historia cada vez con más energía. ¿Qué señales no verbales acompañan mejor el momento?', '["Una postura quieta para no distraerla", "Sonrisas y expresiones que reaccionan a lo que cuenta", "Mirar hacia otro lado para darle espacio", "Ánimos de palabra, sin moverte"]'::jsonb, 'Acompañar su energía con el cuerpo muestra que sigues emocionalmente su historia.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9fcc9a77-636d-4e32-833f-dd1e41b91be5', 'es', '¿Qué señales transmiten distracción?', '["Una expresión facial plana", "El cuerpo girado hacia otro lado", "Reflejar sus expresiones", "Mirar alrededor del lugar"]'::jsonb, 'La quietud sin reacción suele leerse como desinterés.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1e90c6c9-0d3b-47fc-b3ac-599c201f184d', 'es', '¿Qué elementos es más importante acompañar al principio?', '["La profundidad emocional", "El ritmo al hablar", "El volumen y la energía", "Todas las anteriores"]'::jsonb, 'La comodidad al principio nace de acompañar su profundidad emocional, su ritmo y su energía.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6886b3ac-3f9a-4fba-ad87-515db908bb79', 'es', 'Te habla con emoción de algo que le pasó hace poco. ¿Qué podrías hacer primero?', '["Acompañar su tono emocional con empatía", "Responder con un consejo práctico", "Pasar a una anécdota graciosa", "Hacerle preguntas sobre los hechos"]'::jsonb, 'Refleja su tono para mostrar sintonía antes de llevar la conversación a otro lado.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('003c10ec-d480-4896-916d-26f2d942ba10', 'es', '¿Por qué acompañar primero su profundidad y su estilo ayuda a crear conexión?', '["Transmite que se parecen y relaja su sistema nervioso", "Muestra que estás en sintonía con su energía del momento", "Reduce los roces de estar en niveles distintos", "Lleva de inmediato a temas más profundos"]'::jsonb, 'Acompañarla crea sintonía, y eso hace que avanzar se sienta natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3327c759-7a65-49ec-96b3-d70b813c73ef', 'es', '¿Cuál es la forma más eficaz de contar una historia?', '["Contar menos detalles personales", "Contar emociones sin contexto", "Contar experiencias con perspectiva y desenlace", "Evitar por completo mostrarte vulnerable"]'::jsonb, 'Contar bien incluye una reflexión y un desenlace; cuenta lo que aprendiste.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c32cb2cd-cf15-4d66-aa1f-8bc019d02b51', 'es', 'Al principio de la conversación te pregunta: “¿A qué te dedicas?”. ¿Qué respuesta está mejor medida?', '["“Trabajo en tecnología, pero lo odio y no sé qué quiero hacer en su lugar.”", "“Trabajo en tecnología. Es exigente, pero me está enseñando mucho sobre disciplina.”", "“Es complicado. No me gusta mucho hablar de eso.”"]'::jsonb, 'Reconoce la realidad y a la vez muestra perspectiva. Despierta curiosidad, no preocupación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2924bec5-27b6-4372-95e0-97a1b87cd7f5', 'es', '¿Por qué al principio es mejor compartir algo procesado que algo sin procesar?', '["Muestra autoconocimiento y crecimiento", "Evita ponerle a ella una carga emocional", "Invita a la cercanía sin generar presión", "Descarga problemas sin resolver para buscar compasión"]'::jsonb, 'Las experiencias procesadas crean conexión; las que no lo están generan incomodidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('72b691fd-5105-42a5-b902-f35bd796089d', 'es', '¿Cuál es el objetivo principal de contar una historia en una conversación?', '["Impresionarla con tu historia de vida", "Competir con sus historias", "Llenar el tiempo hasta que ella vuelva a hablar", "Revelar algo significativo sobre ti"]'::jsonb, 'Una imagen clara y honesta la ayuda a entenderte rápido.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('26a750bf-98fb-4c3c-a099-407b3b3aabb9', 'es', 'Te pregunta cómo llegaste a tu trabajo actual. ¿Qué podrías contar?', '["Toda tu trayectoria desde tus años de escuela hasta hoy", "Solo tu puesto actual, sin contexto", "Un momento clave que te hizo cambiar de rumbo"]'::jsonb, 'Céntrate en un momento significativo para mostrar con claridad cómo eres y mantener su interés.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2330422b-5fb8-4763-a6cc-a1631f85f12d', 'es', '¿Qué elementos son esenciales en una historia que capta la atención?', '["Un planteamiento con contexto rápido", "Un conflicto o una tensión que haga que algo esté en juego", "Un desenlace o una conclusión", "Fechas y nombres exactos"]'::jsonb, 'Céntrate en lo que quieres que entienda, no en todo lo que pasó.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1ce28b32-b0c8-4221-b1ff-d3645dd9b96d', 'es', '¿Por qué las historias que no conectas con ella crean distancia en vez de conexión?', '["Te hacen parecer egocéntrico y poco interesado en ella", "Hablaste de ti sin incluirla", "Ella espera su turno en lugar de involucrarse en tu historia"]'::jsonb, 'Contar sin conectar crea distancia; invita su punto de vista para mantener viva la conexión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3f38e00a-0c18-4520-94c4-258ed755d84d', 'es', '¿Qué final te devuelve a ella? Tú: “Cuando me mudé aquí, los primeros meses me sentí muy solo”.', '["“En fin, al final me salió bien.”", "“Esa ciudad es difícil al principio.”", "“Mudarse siempre es difícil.”", "“¿Y a ti cómo te ha ido adaptándote?”"]'::jsonb, 'Invitar directamente su punto de vista convierte tu experiencia en terreno compartido.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d6f93781-4c91-4d3e-835b-28dd4c18773b', 'es', '¿Cómo puedes conectar tus historias con ella?', '["Preguntarle cómo manejaría ella la situación que describiste", "Relacionarla con algo que ella mencionó antes", "Elogiar en ella una cualidad o un punto de vista relacionado"]'::jsonb, 'La conexión nace cuando tu historia se vuelve un puente, no una conclusión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('445fcfa0-4ff7-4518-ac38-f732d3f82c0a', 'es', 'Te cuenta detalles personales con soltura y se ríe con facilidad. ¿Qué indica esto?', '["Solo está siendo cortés", "La conexión tiene suficiente peso como para concretar", "Quiere que te vayas", "La interacción sigue siendo superficial"]'::jsonb, 'Que comparta por voluntad propia y con energía muestra que es momento de concretar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('22126888-2232-418e-83ad-f3149c24f572', 'es', 'Te responde con calidez y desarrolla lo que dices. ¿Qué indica esto?', '["La conexión tiene suficiente peso como para concretar", "Está tolerando la conversación", "Quiere que todo sea breve", "La charla sigue siendo superficial"]'::jsonb, 'La calidez y que desarrolle lo que dices indican mucha implicación; es momento de concretar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8c9143a9-92d6-4ec0-bd1d-cc131e69c354', 'es', '¿Cuáles son las señales clave de que es momento de concretar?', '["Te da respuestas cortas y corteses", "Aporta más de lo necesario", "Te hace preguntas sobre ti", "Mantiene la presencia y la curiosidad"]'::jsonb, 'Cuando se implica, te pregunta por ti y sigue metida en la conversación, es momento de concretar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('372fbba5-b4e8-4738-9cf6-186872aed9ae', 'es', '¿Por qué deberías relacionar tu despedida con algo de lo que hablaron?', '["Para sonar atento", "Para crear un motivo natural para volver a hablar", "Para demostrar que estabas prestando atención", "Para aumentar la atracción de inmediato"]'::jsonb, 'Relacionarla con un detalle compartido te da un motivo natural para volver a conectar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4bf82e54-bc68-47b4-954e-9a2f34ad7cee', 'es', 'Tuvieron una buena conversación sobre su próximo viaje. ¿Cuál es la mejor forma de despedirte?', '["“Un gusto conocerte, cuídate”", "“Te dejo seguir con lo tuyo”", "Despedirte rápido para evitar un momento incómodo", "Mencionar el viaje y proponer seguir hablando más adelante"]'::jsonb, 'Una referencia concreta a algo que le importaba mantiene viva la interacción más allá de la despedida.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b6859e08-892e-4454-a9e6-c9d9f7f344eb', 'es', '¿Qué detalles conviene usar al terminar una interacción?', '["Un plan que ella mencionó", "Una broma que compartieron", "Una observación neutra", "Algo que la entusiasmaba"]'::jsonb, 'Los momentos emocionales o compartidos dan más continuidad que un comentario neutro de relleno.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('10646abd-5ffe-4d87-9ebb-9d70bfea0218', 'es', '¿Qué está decidiendo ella cuando intentas concretar?', '["Si eres material para una relación", "Si el siguiente paso se siente cómodo", "Si eres distinto a otros hombres", "Si quiere algo serio"]'::jsonb, 'Los primeros síes tienen que ver con la comodidad, no con el compromiso. Haz que el siguiente paso se sienta fácil.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8d044d58-aac0-440d-9742-83bb3888a6e8', 'es', 'Conversación ligera en un mercado. Buena vibra. ¿Cuál es la mejor forma de concretar?', '["“Deberíamos ir a cenar algún día”", "“No suelo hacer esto, pero ¿me das tu número?”", "“Te paso el lugar de comida del que hablamos”", "“¿Estás libre este fin de semana?”"]'::jsonb, 'Continúa el momento sin convertirlo en un compromiso.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8a141571-c267-4806-9868-387cdb482491', 'es', '¿Qué formas de concretar se sienten sin presión y fáciles de aceptar?', '["“Te paso el lugar que mencionamos”", "“Deberíamos planear una cena para mañana”", "“Sigamos con esto otro día”", "“¿Te puedo invitar a salir este viernes?”"]'::jsonb, 'Estas opciones invitan a seguir sin pedir un compromiso.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('66ba6667-2abd-42f6-a901-d96277d04433', 'es', '¿Cómo convertir preguntas en frases que dan por hecho el siguiente paso?', '["De “¿Te gustaría tomar un café?” a “Vamos a tomar un café”", "De “¿Me das tu número?” a “¿Cuál es tu número?”", "De “¿Quieres que nos volvamos a ver?” a “Volvamos a vernos”", "Todas las anteriores"]'::jsonb, 'Dar por hecho el siguiente paso funciona porque elimina las dudas del momento.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d70c3efb-944b-4b7a-82a9-48ba274ccb86', 'es', '¿Por qué pedir permiso para concretar suele debilitar una buena interacción?', '["Suena demasiado formal", "Activa su mente analítica en lugar de dejarla en el momento", "Te hace parecer arrogante", "Reduce la conexión emocional"]'::jsonb, 'Las preguntas invitan a evaluar, y eso puede interrumpir sensaciones que ya eran positivas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c0286e42-af7f-43c7-ac69-9ab7c6a2e05a', 'es', '¿Qué frases dan por hecho el siguiente paso?', '["“¿Te gustaría, no sé, salir algún día?”", "“Tomemos un café esta semana.”", "“Ponme tu número y te escribo.”", "“¿Te sientes cómoda intercambiando números?”"]'::jsonb, 'Dar por hecho el siguiente paso funciona porque elimina las dudas del momento.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b4f4d3f5-96e1-4f85-964d-0f77451b74c5', 'es', '¿Qué suele indicar una caída de energía en una conversación?', '["Que perdió el interés", "Que la interacción fracasó", "Que dijiste algo mal", "Que el ritmo se apagó y hay que reconducirlo"]'::jsonb, 'Las caídas de energía son transiciones normales, no señales de rechazo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8c543af2-ac46-444f-8c77-92edfd929224', 'es', 'Notas respuestas más cortas después de cambiar de tema. ¿Qué es una buena reacción?', '["Hacer una pregunta más profunda para recuperar el ritmo", "Señalar que el momento se puso incómodo", "Hacer una breve pausa y pasar a un tema más ligero y neutro", "Dejar de hablar y que ella reconduzca"]'::jsonb, 'Reconducir con calma recupera el ritmo sin añadir presión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1cdf68f6-8aa9-43b3-9ce5-b644e615778c', 'es', 'La energía puede caer porque:', '["un tema ya dio todo lo que tenía que dar", "alguien tocó un tema neutro o delicado", "el ritmo cambió de forma natural", "la atracción desapareció de golpe"]'::jsonb, 'Una caída de energía suele indicar un cambio, no una pérdida de atracción; ajusta el tema o el ritmo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('39b1d59b-f33e-478c-9666-991b209c27d4', 'es', '¿Qué regla interna te ayuda más a no estar de acuerdo sin desconectar?', '["No cuestionar nunca sus opiniones", "Explicar siempre tu razonamiento completo", "Mantener la conversación ligera a toda costa", "Ver las diferencias como algo que entender, no que vencer"]'::jsonb, 'Entender mantiene la conexión. Ganar, no.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c7c5b822-4135-4f6f-8bdf-de37566401d8', 'es', 'Te da una opinión con la que no estás de acuerdo. ¿Qué deberías evitar?', '["Preguntarle: “¿Por qué lo ves así?”", "Insistir para convencerla de que tienes razón", "Reconocer su punto de vista antes de dar el tuyo", "Mantener la curiosidad por su perspectiva"]'::jsonb, 'Imponer tu punto de vista puede volverse una pelea y rompe el ritmo de la conversación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('01a6207d-b8f9-4037-8efa-858f6eca585f', 'es', '¿Por qué no estar de acuerdo, bien llevado, puede aumentar la atracción?', '["Crea drama", "Muestra autenticidad", "Demuestra que no estás actuando para ganarte su aprobación", "Marca tu superioridad"]'::jsonb, 'La gente responde a la autenticidad, no a los intentos de ganarse su aprobación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bcc09860-096f-4e3f-af27-42276cd9f883', 'es', '¿Por qué es importante que te asocie con emociones positivas?', '["Las emociones crean asociaciones más fuertes contigo", "Sentirse bien hace que quiera pasar más tiempo contigo", "Las dos anteriores"]'::jsonb, 'La atracción se construye a partir de cómo se siente cuando está contigo, no solo de lo que dicen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f1e9a61d-15cb-4f8b-af34-a49ba9147cfd', 'es', 'Notas que la conversación se está poniendo pesada. ¿Cuál es la mejor jugada?', '["Cambiar de tema de golpe", "Añadir lógica o consejos", "Meter un toque juguetón o de imaginación", "Disculparte por el ambiente"]'::jsonb, 'La ligereza reajusta el tono emocional sin llamar la atención sobre la caída.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ed64c038-1dd6-4294-ab5d-a11f9b7c1095', 'es', '¿Qué recursos en la conversación ayudan a que te asocie con emociones positivas?', '["Imaginar un alivio o un disfrute futuro", "Ser juguetón sin forzar las bromas", "Restarle importancia a lo que le preocupa", "Hacer preguntas que inviten a reflexionar"]'::jsonb, 'Estos recursos elevan su estado emocional sin quitarle validez a lo que vive.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0031e3a0-ef4a-44e3-a000-6ae183b1956c', 'es', '¿Por qué apresurarte a responder suele reducir la conexión?', '["Suena a guion", "Le quita el espacio para seguir", "Se siente demasiado lógico", "Acorta la conversación"]'::jsonb, 'La prisa puede saturar el momento e impedir que ella se extienda.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('01f54d1a-679b-4a40-80b2-cdc59c6849ef', 'es', '¿Qué pasa cuando te quedas callado demasiado a menudo en una conversación?', '["La obliga a cargar con la interacción", "Crea misterio", "Genera expectativa", "Muestra seguridad"]'::jsonb, 'El silencio sin aportar nada carga injustamente el esfuerzo sobre ella.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('021ce377-a3dd-4de9-9114-c7227778650f', 'es', 'Te dice “Yo lo veo distinto” y hace una pausa. ¿Cuál es la mejor jugada?', '["Corregirla con suavidad", "Preguntarle qué la llevó a verlo así", "Defender tu postura de inmediato", "Cambiar de tema para evitar roces"]'::jsonb, 'Invitar su punto de vista mantiene la interacción en un tono de colaboración.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('03069501-c343-419c-9422-a171d3aefb45', 'es', '¿Qué hace que un desacuerdo dañe la conexión?', '["Tener opiniones opuestas", "Expresar opiniones firmes", "Darle más prioridad a tener razón que a seguir conectados", "Hablar de temas serios"]'::jsonb, 'No es el desacuerdo lo que genera tensión, sino la necesidad de demostrar algo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0fb4b26d-dc3b-4250-9c5f-8ff9ea4885aa', 'es', '¿Por qué al principio funcionan mejor las propuestas pequeñas y sin presión?', '["Se sienten como una continuación natural del momento", "Le permiten decir que sí sin tener que evaluarlo mucho", "Activan su instinto de proteger sus límites"]'::jsonb, 'Las propuestas sin presión bajan las defensas; pide poco para que el sí salga natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('15ae2762-769f-4714-8d54-0a1d42a10930', 'es', '¿Qué resume mejor la escucha no verbal?', '["Dejar que tu cuerpo responda visiblemente a sus palabras", "No interrumpir", "Hacerte el expresivo", "Mantener el silencio"]'::jsonb, 'La escucha se comunica con el cuerpo antes de expresarse con palabras.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1a509b2e-e316-4bf7-a46a-0c9212bf889f', 'es', '¿Qué hace que concretar se sienta fácil y no exigente?', '["Plantear la propuesta de forma que decir que sí sea lo más fácil", "Darle varias opciones para que sienta que tiene el control", "Presentar la decisión resaltando las ventajas"]'::jsonb, 'El objetivo es que decir que sí se sienta fácil, quitando presión y manteniéndolo sencillo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1b58b79f-3bec-4098-a37d-6b534a17056a', 'es', 'Sonríe con naturalidad y deja lo que estaba haciendo para centrarse en ti. ¿Qué significa?', '["Está siendo cortés, pero no le interesas", "Primero necesita más charla casual", "Está implicada y es momento de concretar", "Está lista para terminar la interacción"]'::jsonb, 'Una sonrisa genuina y toda su atención muestran que es momento de concretar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1c45a74c-59e6-49a8-abc6-c4f1e648d603', 'es', '¿Qué rompe el ritmo de una conversación?', '["Que uno hable demasiado sin hacer pausas", "Que uno se quede callado y no aporte", "Cambiar de tema a menudo antes de explorar uno a fondo", "Todas las anteriores"]'::jsonb, 'Un buen ritmo nace de saber cuándo hablar y cuándo parar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('20617380-7250-45ce-9ef3-db838e43f344', 'es', 'Te dice “He tenido mucho trabajo” mientras suelta el aire y se encoge. ¿Qué indica probablemente?', '["Que le gusta ser productiva", "Que quiere un consejo", "Que está cambiando de tema", "Que está dejando ver cansancio o estrés"]'::jsonb, 'Las señales no verbales suelen revelar más que las propias palabras.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('26b9d0d1-6a3e-46d5-8be6-4fce70caa793', 'es', 'Menciona que la semana que viene empieza una clase de cerámica. ¿Qué despedidas funcionan bien?', '["“¡Suerte con la cerámica!”", "“¿Clase de cerámica? Me tienes que enseñar lo que hagas.”", "“Quiero saber cómo te va en la primera clase.”", "“¡Qué bien! Deberíamos vernos algún día.”"]'::jsonb, 'Relacionarla con un hilo de la conversación te da un motivo natural para volver a conectar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('27419754-77e6-40e3-9216-e374c74f4e85', 'es', '¿Cuál es la clave de una conversación equilibrada?', '["Mezclar preguntas con observaciones y comentarios", "Usar solo preguntas para que fluya", "Aportar tus propias ideas y tu atención", "Dejar que ella ponga todo el contenido"]'::jsonb, 'El equilibrio nace de que los dos aporten, no de sacarle información.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2bd11bb2-0b86-43aa-b35b-b9370dcdcbdc', 'es', 'Está bromeando en tono ligero sobre su día. ¿Cuál es la mejor respuesta?', '["Contarle un problema personal serio", "Quedarte callado y dejar que ella lleve la conversación", "Hacerle una pregunta profunda sobre sus valores", "Seguirle el humor y añadir un pequeño detalle juguetón"]'::jsonb, 'Acompañar su ligereza mantiene intacto el ritmo y conserva el impulso.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('30047758-bc26-4c9c-b253-e6f994f1b01c', 'es', '¿Cuándo es apropiado compartir dificultades sin procesar?', '["Cuando ya hay una confianza y una base sólidas", "Nunca; procesa siempre las experiencias antes de contarlas", "Cuando necesitas rápido su apoyo emocional"]'::jsonb, 'Compartir algo sin procesar necesita una base lo bastante sólida para soportar el peso.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3133663f-3070-4a86-ace7-3cb3f7ad86cc', 'es', 'Te cuenta una experiencia difícil con un suspiro. ¿Qué deberías evitar?', '["Decir: “Suena difícil. ¿Qué te ayudó a salir adelante?”", "Saltar a: “¿Has probado a hacerlo así?”", "Comentar: “Entiendo por qué fue duro.”", "Preguntar: “¿Cómo te hizo sentir eso?”"]'::jsonb, 'Un consejo sin reconocer lo que siente da la impresión de que no captaste lo que quería decir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('31d09412-eae6-4340-9ae4-3e41fb01548a', 'es', 'Te contó que le encanta una banda que les gusta a los dos. Al despedirte, ¿qué podrías hacer?', '["Decir “Un gusto conocerte”", "Mencionar la banda y proponer intercambiar números para pasarse música", "Hacerle una pregunta más sin relación"]'::jsonb, 'Usa un detalle compartido en la despedida para conservar la conexión y el ritmo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('334df846-2984-4745-ad56-48b235d5dc09', 'es', '¿Por qué asentir a todo para no llevarle la contraria debilita la atracción?', '["Se siente deshonesto", "Transmite inseguridad o búsqueda de aprobación", "Le quita profundidad a la conversación", "Todas las anteriores"]'::jsonb, 'Evitar las diferencias te hace pasar a segundo plano y te quita autenticidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('33959938-2cf9-429c-889b-15d1b785f535', 'es', '¿Cuál es la diferencia principal entre escuchar para responder y escuchar para entender?', '["Centrarte en ti o centrarte en ella", "El nivel de seguridad", "La rapidez de la respuesta", "Cuánto se habla"]'::jsonb, 'La diferencia está en dónde pones tu atención durante la interacción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('353e58e9-544b-4f89-8b9f-2806e9bbc67f', 'es', '¿Qué psicología explica que las propuestas pequeñas funcionen mejor que las grandes?', '["La gente dice que sí con más facilidad cuando la propuesta no presiona", "Las propuestas pequeñas demuestran seguridad porque no dependes del resultado", "Lo pequeño reduce el miedo al rechazo de los dos lados"]'::jsonb, 'Las propuestas sin presión bajan las defensas; pide poco para que el sí salga natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('35bf5d25-82d5-4369-ade9-a66744b2cd83', 'es', '¿Qué pregunta interna te ayuda a elegir la historia correcta para contar?', '["“¿Esto impresiona?”", "“¿Estoy cubriendo todo?”", "“¿Qué es lo único que quiero que entienda?”", "“¿Cuánto tiempo llevo hablando?”"]'::jsonb, 'Céntrate en lo que quieres que entienda, no en todo lo que pasó.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('36112ad3-3e6a-4b43-8ba4-e67ceaa9859d', 'es', 'Te fijas en que su funda de celular es muy original. ¿Qué respuesta es una observación?', '["“¿Dónde conseguiste esa funda?”", "“Esa funda está genial.”", "“¿Te gusta tu celular?”", "“¿Qué modelo es tu celular?”"]'::jsonb, 'Una observación muestra que prestas atención y le da algo a lo que responder.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3722ef90-5c5e-45fb-bb2f-2f8a5e572077', 'es', '¿Cuál es la diferencia clave entre compartir algo procesado y algo sin procesar?', '["Lo procesado siempre es positivo; lo no procesado, negativo", "Lo procesado son lecciones aprendidas; lo no procesado, un dolor sin resolver", "Lo procesado genera presión; lo no procesado crea confianza"]'::jsonb, 'Cuenta la lección, no la herida, para no cargarla emocionalmente.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('37f350f5-2279-4994-9c9e-3ad922169129', 'es', '¿Por qué retomar hilos evita el cansancio de la charla casual?', '["Exploras temas con sentido en lugar de intercambios superficiales", "Construir sobre sus hilos crea un intercambio real en vez de un interrogatorio forzado", "Retomar hilos muestra interés y que escuchaste lo que tenía que decir", "Todas las anteriores"]'::jsonb, 'Retomar hilos profundiza los temas, quita la sensación de entrevista y hace que se implique más.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('38aecf14-80ce-4eef-8327-98612dfd5568', 'es', 'Te cuenta una historia y sientes ganas de relacionarla con algo tuyo. ¿Cuál es la mejor jugada?', '["Contar tu historia después", "Contenerte y reflejar primero lo que ella contó", "Cambiar de tema para mantener el ritmo", "Darle un consejo para aportar valor"]'::jsonb, 'Reflejar antes de hablar de ti mantiene el foco en entenderla.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
